import { projectStatusMarkdown } from './project.mjs';
import { uiPages, heartExamples } from './ui-guides.mjs';
export const pages=[];
const add=(route,title,description,body,options={})=>pages.push({route,title,description,body: (['comece/visao-geral','versoes/estado-da-versao'].includes(route) ? projectStatusMarkdown+'\n\n' : '')+body,options});
const api=(name)=>`[${name}]($BASE/api/astra-${name.toLowerCase()}/)`;
const guide=(route,title,description,sections)=>add(route,title,description,sections.map(([h,p])=>`## ${h}\n\n${p}`).join('\n\n'));

guide('comece/visao-geral','O seu primeiro universo','Entenda a Astra e escolha um caminho para começar.',[
['O que você vai encontrar','Astra combina autoria de cenas, componentes e comportamentos C#. Você organiza objetos, configura suas propriedades e executa o resultado em Play. Este portal documenta a geração atual em um snapshot de 06/10/2026.'],
['Escolha sua trilha','- **Primeiro contato:** siga [primeiro projeto]($BASE/comece/primeiro-projeto/), [primeira cena]($BASE/comece/primeira-cena/) e [primeiro script]($BASE/comece/primeiro-script-c/).\n- **Criação visual:** consulte o [mapa de acesso]($BASE/editor/mapa-de-acesso/) e o [catálogo de componentes e campos]($BASE/componentes/).\n- **HUD e interface:** siga [onde fica a UI]($BASE/ui/comece-aqui/) e [corações com dano/cura]($BASE/ui/hud-coracoes/).\n- **Programação:** abra a [API C#]($BASE/api/), com acesso, uso e roadmap em cada membro. As assinaturas são extraídas semanticamente do código.'],
['Como ler os estados','“Conferido em fonte” identifica um contrato observado no código. “Referência de assinaturas” não afirma que cada método foi testado em um aparelho. Os exemplos novos declaram separadamente sua compilação e execução. Consulte a [cobertura da versão]($BASE/versoes/estado-da-versao/).'],
['Antes de começar','Baixe a prévia pública na [página de download](/download/), confira os requisitos e preserve seus projetos antes de instalar. Não misture estes exemplos C# com o planejamento de Astra 2/Luau.']]);
guide('comece/requisitos-e-compatibilidade','Requisitos e compatibilidade','Separe os requisitos da instalação dos requisitos de uma cena.',[
['Instalação e geração','Esta documentação corresponde à Astra atual, com API C# e renderer Vulkan no Android. A compatibilidade deve ser conferida para o APK efetivamente distribuído; um modelo de aparelho ou a presença de Vulkan, isoladamente, não confirma todos os recursos.'],
['Antes de importar uma cena','Verifique espaço livre para arquivos originais e derivados, memória disponível, texturas, quantidade de geometria e recursos referenciados. Importar um arquivo não garante que todo recurso da ferramenta que o exportou terá equivalente na Astra.'],
['Como registrar um problema','Anote a versão da engine, aparelho/GPU, versão do Android, cena, resolução e qualidade. Informe se o erro ocorre ao abrir o projeto, iniciar Play ou retomar o aplicativo. Veja [limites e capacidades]($BASE/conceitos/limites-e-capacidades/).']]);
guide('comece/instalacao','Instalação','Prepare uma instalação compatível antes de seguir os tutoriais.',[
['Distribuição deste snapshot','A prévia pública para Android está na [página de download](/download/), com versão, requisitos, tamanho e SHA-256. Baixe o APK no aparelho, abra o arquivo e autorize a instalação pelo navegador quando o Android solicitar. O pacote exige Android 8.0+, ARM64 e Vulkan 1.1.'],
['Preserve seus projetos','Antes de substituir uma instalação existente, mantenha uma cópia dos projetos fora dos dados do aplicativo. A prévia pública usa uma assinatura de distribuição própria: se a instalação anterior tiver outra assinatura, o Android exigirá reinstalação. Desinstalar pode apagar projetos locais. Não limpe os dados do aplicativo para resolver uma falha de migração sem preservar os arquivos.'],
['Depois de instalar','Abra a lista de projetos e crie um projeto vazio. Entre no editor, salve uma cena simples e reabra o projeto antes de importar conteúdo grande. Continue em [primeiro projeto]($BASE/comece/primeiro-projeto/).']]);
guide('comece/primeiro-projeto','Seu primeiro projeto','Comece com uma cena pequena e um resultado fácil de conferir.',[
['Crie a base','Na tela de projetos, use a ação de criar projeto, escolha um nome identificável e abra a cena vazia. A disponibilidade de modelos depende da versão instalada; não trate projetos demonstrativos históricos como modelos obrigatórios.'],
['Organize antes de crescer','Use nomes que descrevam a função dos objetos. Separe o objeto que receberá o comportamento, a câmera e os elementos do ambiente. O editor de cena trabalha em landscape; a área de código pode usar outra orientação.'],
['Faça uma primeira gravação','Salve o projeto, volte à lista e reabra. Confira nome, objetos e transformações. Essa pequena conferência separa problemas de persistência de problemas que poderiam aparecer depois da importação.'],
['Próximo resultado','Crie uma [primeira cena]($BASE/comece/primeira-cena/) e adicione um comportamento de rotação. O objetivo inicial é observar uma mudança simples em Play e recuperar a cena autoral ao parar.']]);
guide('comece/conheca-o-editor','Conheça o editor','Viewport, Hierarquia, Inspector e código têm papéis diferentes.',[
['Viewport e seleção','O viewport mostra a cena. A Hierarquia permite localizar um objeto mesmo quando ele está fora da câmera ou encoberto. Selecione um objeto antes de procurar suas propriedades.'],
['Inspector e componentes','O Inspector apresenta os dados do objeto selecionado. Transformação posiciona o objeto; componentes acrescentam comportamento e dados especializados. Campos podem aparecer somente quando uma configuração os torna relevantes.'],
['Código, console e execução','A área de código edita comportamentos C#. Compile antes de entrar em Play. Consulte as mensagens de diagnóstico quando um script não carregar; uma edição de texto não significa que a nova versão já está executando.'],
['Continue','Leia [Viewport e navegação]($BASE/editor/viewport-e-navegacao/), [Inspector]($BASE/editor/inspector/) e [Play e Stop]($BASE/comece/play-e-stop/).']]);
guide('comece/primeira-cena','Sua primeira cena','Monte um cenário mínimo para observar um objeto em Play.',[
['Composição','Crie uma primitiva visível, uma câmera com enquadramento útil e iluminação adequada ao material. Prefira uma forma assimétrica para testar rotação; uma esfera lisa pode girar sem produzir uma mudança visual perceptível.'],
['Posição e enquadramento','Selecione a geometria na Hierarquia e confira sua escala. Posicione a câmera de modo que o objeto fique entre os planos próximo e distante. A câmera de edição e a câmera de gameplay não precisam compartilhar a mesma pose.'],
['Salve e observe','Salve a cena antes de Play. Confirme se o objeto aparece na câmera do jogo. Se a imagem estiver vazia, consulte [câmera sem imagem]($BASE/diagnostico/camera-sem-imagem/).'],
['Adicione comportamento','Continue com [primeiro componente]($BASE/comece/primeiro-componente/) ou [primeiro script C#]($BASE/comece/primeiro-script-c/).']]);
guide('comece/primeiro-componente','Seu primeiro componente','Adicione uma capacidade pelo seu contrato de composição.',[
['Escolha pela função','Selecione um objeto e abra a ação de adicionar componente. Use o [catálogo]($BASE/componentes/) para localizar o nome no editor, requisitos e conflitos. Um tipo listado em uma referência de outra engine não está automaticamente disponível na Astra.'],
['Resolva a composição','O schema pode exigir outros componentes no mesmo objeto. Também pode recusar uma combinação por conflito de autoridade, como dois sistemas que tentam publicar a mesma transformação. Leia o motivo apresentado em vez de remover dependências ao acaso.'],
['Confira uma propriedade','Altere um campo com efeito observável e mantenha os demais valores estáveis. Observe o resultado, desfaça e refaça. Salve e reabra para verificar o estado autoral.'],
['Durante Play','Consulte na página do tipo se a mudança estrutural é permitida. Operações em ponto seguro não devem ser tratadas como execução imediata dentro de um callback.']]);
const rotate=`using Astra;
using System.Numerics;

[ComponentId("docs.rotate-object")]
public sealed class RotateObject : Behavior
{
    public override void Update(float deltaTime)
    {
        Object.Rotate(Vector3.UnitY, 0.5f * deltaTime,
                      TransformSpace.Local);
    }
}`;
add('comece/primeiro-script-c','Seu primeiro script C#','Faça um objeto girar a 0,5 rad/s com um Behavior.',`## Prepare a cena

Use um objeto visível, sem corpo físico nem controlador de personagem comandando sua pose. Prefira geometria assimétrica. Crie um script C# e anexe o comportamento ao objeto pela área de código.

## Código completo

\`\`\`csharp title="RotateObject.cs"
${rotate}
\`\`\`

O identificador de componente é estável e deve ser único no projeto. A taxa de 0,5 rad/s é multiplicada uma vez pelo intervalo de atualização. A Astra usa **radianos** nesta operação.

## Compile e observe

Compile no editor e resolva os erros antes de iniciar Play. O resultado esperado é a rotação em torno do eixo Y local. Pare a execução e confira a cena autoral. Este exemplo foi preparado para esta API; a execução no aparelho não foi realizada nesta publicação.

## Se o objeto não girar

Confira se o comportamento está anexado e habilitado, se o objeto recebe atualização e se outro sistema escreve a orientação depois dele. Consulte ${api('GameObject')} e [autoridade de transformação]($BASE/conceitos/autoridade-de-transformacao/).

[Baixar RotateObject.cs](/examples/rotate-object/RotateObject.cs)`);
guide('comece/play-e-stop','Play e Stop','Entenda o que está executando e o que pertence à cena autoral.',[
['Antes de Play','Salve a cena e compile os scripts. O mundo de execução é criado a partir dos dados autorais; callbacks e recursos pertencem àquela sessão.'],
['Enquanto executa','Objetos podem ser criados, removidos ou alterados por scripts. Certas operações são enfileiradas para um ponto seguro. A interface do editor pode capturar entrada e suspender a resposta do gameplay.'],
['Ao parar','Referências da sessão encerrada deixam de ser válidas. Não armazene handles entre sessões e não suponha que uma transformação aplicada por script foi gravada na cena autoral. Para progresso do jogador, use [persistência]($BASE/sistemas/persistencia/).']]);
guide('comece/salvar-e-reabrir','Salvar e reabrir','Confira persistência com mudanças identificáveis e recuperáveis.',[
['O que salvar','A cena autoral descreve objetos, composição e propriedades persistentes. O progresso de gameplay possui outro contrato. Salvar uma cena não equivale a executar SaveStore.Flush.'],
['Conferência prática','1. Selecione um objeto e altere nome ou posição.\n2. Salve e encerre a edição normalmente.\n3. Reabra o projeto.\n4. Confira a mesma propriedade e as referências a recursos.\n5. Entre em Play somente depois dessa conferência.'],
['Se a leitura falhar','Preserve o arquivo e seus backups. Uma versão desconhecida, recurso ausente ou arquivo truncado exige diagnóstico; não sobrescreva imediatamente a única cópia. Veja [cena não reabre]($BASE/diagnostico/cena-nao-reabre/).']]);
guide('comece/proximos-passos','Próximos passos','Transforme a primeira cena em um sistema pequeno e observável.',[
['Expanda uma variável por vez','Depois da rotação, experimente [movimento local]($BASE/receitas/mover-em-espaco-local/). Em seguida, escolha input, câmera ou física. Alterar tudo ao mesmo tempo dificulta identificar a origem de um erro.'],
['Escolha a referência certa','Use o manual para descobrir o fluxo do editor, o catálogo para compor objetos, a API para conferir assinaturas e as receitas para combinar sistemas.'],
['Conserve um caso mínimo','Mantenha uma cópia pequena que reproduz o comportamento. Registre versão e resultado esperado antes de adicionar assets, efeitos e cenas maiores.']]);

const editor=[
['projetos-e-modelos','Projetos e modelos','Organize a cena e os recursos como uma unidade de trabalho.','Um projeto agrupa cenas, scripts e recursos. Começar vazio facilita identificar dependências; um exemplo pronto pode trazer composição e configurações próprias. Não presuma que todos os exemplos históricos estão distribuídos como templates.','Dê nomes distintos aos experimentos. Antes de importar ou migrar, preserve uma cópia do projeto. Confira referências ao reabrir, especialmente quando os recursos foram movidos fora do editor.','comece/primeiro-projeto'],
['viewport-e-navegacao','Viewport e navegação','Use a cena como área principal de trabalho.','A câmera do editor serve à inspeção. A câmera de gameplay é um objeto com configuração própria. Use a Hierarquia para selecionar e enquadrar objetos que não estão visíveis; um viewport de edição correto não prova que a câmera do jogo está configurada.','Trabalhe em landscape no editor de cena. Recolha superfícies que não precisa consultar durante a manipulação. Ao investigar um problema de enquadramento, confira transformações, projeção e planos de recorte.','diagnostico/camera-sem-imagem'],
['selecao-e-multisselecao','Seleção e multisseleção','Saiba qual objeto e qual conjunto uma ação vai alterar.','A seleção liga Hierarquia, gizmo e Inspector. Antes de editar um componente, confira o nome do alvo. Com vários objetos selecionados, uma propriedade pode representar valores diferentes e uma ação pode atuar sobre todo o conjunto.','Faça uma mudança pequena, observe os objetos afetados e use Undo para conferir a transação. Se o alvo estiver encoberto, selecione pela Hierarquia em vez de insistir no toque sobre geometria sobreposta.','editor/undo-e-redo'],
['hierarquia-e-parenting','Hierarquia e parenting','Relacione objetos sem perder a distinção entre local e mundo.','A transformação local é relativa ao pai. Mudar de pai pode manter a pose local ou tentar preservar a pose de mundo; essas escolhas produzem resultados diferentes. A API explicita a política de reparenting.','Não crie ciclos. Escalas e matrizes que não podem ser representadas por transformação válida podem impedir a operação. Confira posição, rotação e escala após mover um objeto na árvore.','conceitos/espaco-local-e-mundo'],
['gizmos-e-coordenadas','Gizmos e coordenadas','Alterne entre manipulação visual e valores precisos.','O gizmo transforma o objeto selecionado. Local e mundo definem a orientação dos eixos. Valores do Inspector ajudam quando é necessário repetir uma distância, alinhar objetos ou corrigir uma escala.','Confira a unidade do campo. Rotate em C# usa radianos, enquanto um campo de lente pode declarar graus. O rótulo e o contrato da propriedade têm prioridade sobre hábitos de outras engines.','conceitos/unidades-e-convencoes'],
['inspector','Inspector','Leia os dados do objeto e as condições de cada propriedade.','O Inspector mostra transformações e componentes do objeto selecionado. Propriedades condicionais aparecem de acordo com o estado: uma lente ortográfica e uma perspectiva não exigem os mesmos controles.','Consulte o catálogo para padrões e intervalos. Um campo restrito pode depender de recurso, slot ou autoridade de runtime. Não interprete a ausência de um campo como perda do valor sem conferir sua condição.','componentes'],
['adicionar-componentes','Adicionar componentes','Monte um objeto com dependências reais.','O catálogo de criação é alimentado pelo schema. Procure pelo nome no editor ou pela função. Scripts Behavior e ferramentas especializadas podem ter criação própria e não aparecem necessariamente no Add genérico.','Ao adicionar, confira os componentes exigidos no mesmo objeto. Ao remover, verifique se outro componente ainda depende daquele tipo. O motivo da recusa é parte do contrato.','editor/dependencias-e-conflitos'],
['dependencias-e-conflitos','Dependências e conflitos','Entenda por que uma composição pode ser recusada.','Uma dependência precisa estar presente para o consumidor funcionar. Um conflito impede dois tipos de coexistirem, por exemplo quando ambos reivindicam a pose. Essas regras são publicadas nas páginas de componentes.','Resolva a cadeia completa de dependências. Remova o dependente antes da dependência quando necessário. Consulte também se a alteração estrutural é permitida durante Play.','conceitos/composicao-de-componentes'],
['assets-e-importacao','Assets e importação','Recursos importados possuem identidade e dependências.','Importar envolve interpretar o formato, resolver imagens e materiais, gerar derivados e registrar identidades. Um arquivo aceito pelo importador ainda pode conter recursos sem equivalente no backend.','Preserve os originais. Confira mensagens sobre dependências ausentes, materiais e animações. Reabra o projeto depois de importar e teste a instância na cena real antes de excluir a fonte.','sistemas/importacao-glb'],
['materiais-e-texturas','Materiais e texturas','Separe o recurso compartilhado dos ajustes por instância.','Material define a resposta visual e referências de textura. Alterar um recurso compartilhado pode afetar vários objetos; um override por instância deve ser tratado como uma camada diferente.','Observe a mesma superfície sob luz estável. Confira cor linear, rugosidade, metalicidade, emissão, alfa e normal conforme o contrato disponível. Ausência de textura não deve ser confundida com um valor escalar incorreto.','sistemas/materiais'],
['codigo-e-compilacao','Código e compilação','Uma edição só entra em execução depois de compilada e carregada.','Behaviors C# declaram um identificador estável e callbacks de lifecycle. Compile o projeto, leia o primeiro erro e confira a assinatura na referência desta versão. Não traduza exemplos da Unity por substituição de nomes.','Um script que compila ainda pode depender de objetos ou recursos ausentes. Confira anexação, enabled e diagnóstico da sessão. Use um comportamento mínimo para separar falha de compilação de falha de runtime.','diagnostico/erros-de-compilacao'],
['console-e-diagnostico','Console e diagnóstico','Use a mensagem, a fase e o alvo para localizar o problema.','Uma falha em Awake tem contexto diferente de uma escrita recusada em Update. Registre o texto completo e a operação. WorldStatus distingue referências vencidas, componente ausente, autoridade física e limite de capacidade.','Corrija a primeira causa reproduzível antes de tratar mensagens posteriores. Evite repetir uma operação inválida a cada frame: isso aumenta ruído e custo sem resolver a configuração.','diagnostico/handle-invalido'],
['undo-e-redo','Undo e Redo','Revise alterações autorais por transação.','Uma operação de autoria pode mudar vários valores relacionados. Undo e Redo trabalham sobre o histórico do editor; não são uma máquina do tempo para toda a simulação de Play.','Após um arraste, use Undo uma vez e observe o que foi restaurado. Salvar e desfazer têm propósitos diferentes. Para operações de importação e mudanças de formato, mantenha uma cópia adicional.','comece/salvar-e-reabrir'],
['busca-global','Busca global','Encontre a informação usando o vocabulário do editor ou da API.','Neste portal, Ctrl/Cmd+K abre a busca de documentação. Ela indexa o conteúdo publicado deste snapshot, incluindo nomes de componentes, tipos e membros. Escape fecha a busca.','No catálogo, combine texto e família; o filtro fica na URL para poder compartilhar a consulta. Uma busca sem resultado não comprova ausência de capacidade na engine: confira a cobertura editorial. Os atalhos do portal não são atalhos do editor.','ia/indice-markdown'],
['atalhos-e-gestos','Atalhos e gestos','Distinga os comandos do portal dos gestos do editor.','No portal, Tab percorre links e controles, Ctrl/Cmd+K abre a busca e Escape fecha o diálogo. O menu de navegação fica recolhido em telas estreitas. Código possui ação de cópia.','No editor, a interpretação do toque depende da ferramenta ativa e da superfície com foco. Teclado, modal e manipulação podem capturar input que iria ao jogo. Esta página não publica um mapa de gestos não verificado para cada versão.','sistemas/input-e-acoes'],
['preferencias','Preferências','Ajustes de leitura e políticas da cena têm escopos distintos.','O tema claro/escuro deste portal pode ser escolhido no controle de tema e acompanha sua preferência local. Isso não altera o tema, a qualidade ou o estado do editor Astra.','Na engine, confira se um ajuste pertence ao aplicativo, projeto, cena ou sessão de Play antes de esperar que ele acompanhe uma exportação. Para investigar custo gráfico, registre os valores efetivos de qualidade e resolução.','desempenho/qualidade-e-resolucao'],
];
for(const [slug,title,description,concept,workflow,related] of editor)guide(`editor/${slug}`,title,description,[['Como funciona',concept],['Fluxo de trabalho',workflow],['Continue',`Consulte [${related.split('/').at(-1).replaceAll('-',' ')}]($BASE/${related}/). A descrição é baseada no contrato atual; capturas e aceite físico de cada fluxo não foram produzidos nesta publicação.`]]);

const concepts=[
['objetos-e-identidade','Objetos e identidade','Objetos são referências a uma cena e a uma sessão.','Um GameObject não é somente um nome: a identidade inclui o mundo e a geração que permitem detectar referências vencidas. Renomear não deve ser usado como mecanismo para invalidar handles.','Use IsAlive/IsValid quando precisar verificar uma referência conservada. Uma busca por nome pode ser ambígua; mantenha referências explícitas para relações importantes.','GameObject'],
['composicao-de-componentes','Composição de componentes','O objeto reúne capacidades com regras compartilhadas.','Componentes acrescentam dados e comportamento. O registro define identidade persistente, propriedades, requisitos, conflitos, multiplicidade e mutabilidade em Play.','Adicionar por API não elimina as regras do editor. Uma composição inválida deve ser corrigida; não ignore WorldStatus.ComponentUnavailable ou ComponentInUse.','Component'],
['handles-e-lifetime','Handles e lifetime','Uma referência só vale enquanto o seu proprietário existir.','Destruir um objeto ou encerrar Play invalida referências. Uma referência de outra sessão não deve ser reaproveitada mesmo quando o nome ou o número do objeto parecem iguais.','StaleHandle indica uma referência vencida; ForeignWorld indica outra execução. Resolva o alvo novamente no lifecycle adequado e cancele trabalho que sobreviveria ao dono.','WorldStatus'],
['cenas-e-recursos','Cenas e recursos','A cena instancia relações; os recursos possuem identidade própria.','Geometria, texturas, scripts, áudio e cenas podem ser recursos referenciados. A identidade de um recurso não é necessariamente o caminho mostrado no navegador de arquivos.','Verifique dependências e tipos ao atribuir recursos. ResourceTypeMismatch e UnknownResource pedem correção da referência, não uma tentativa de interpretar qualquer arquivo como outro tipo.','AssetGuid'],
['espaco-local-e-mundo','Espaço local e mundo','Escolha o referencial antes de somar um deslocamento ou rotação.','Local interpreta a operação na orientação do objeto; World usa o referencial global. Hierarquia e escala do pai afetam a relação entre esses espaços.','TransformPoint inclui translação; TransformDirection trata direção; TransformVector também considera a transformação vetorial. Não substitua um pelo outro só porque todos retornam Vector3.','GameObject'],
['unidades-e-convencoes','Unidades e convenções','Confira a unidade no contrato de cada campo.','GameObject.Rotate recebe radianos. O campo vertical_fov da câmera declara graus. Campos de distância podem declarar metros, tempo usa segundos e cores podem estar em RGB linear.','Converta graus para radianos com graus * PI / 180. Ao integrar uma velocidade, multiplique por deltaTime uma vez. Não extrapole a unidade de uma API para todas as propriedades do Inspector.','TransformSpace'],
['lifecycle-de-behavior','Lifecycle de Behavior','Use a fase adequada para inicializar, atualizar e liberar.','Behavior expõe Awake, Enable, Start, Update, FixedUpdate, LateUpdate, Disable, Stop e Destroy, além de eventos especializados. Nem todas as fases têm o mesmo propósito ou frequência.','Inicialize referências na fase de criação apropriada. Use o intervalo recebido pelo callback de atualização. Libere inscrições e trabalho associado ao dono ao encerrar; não mantenha handles de Play antigo.','Behavior'],
['play-e-cena-autoral','Play e cena autoral','Estado de execução e dados de autoria são domínios separados.','O mundo de Play pode criar objetos e trocar cenas sem substituir o documento autoral. Scenes.Load solicita a troca no fim do quadro; a cena editada volta ao parar o Play.','Não use escrita em Transform como mecanismo de gravação de progresso. Use a autoria para salvar cenas e SaveStore para persistência de gameplay.','ScenesAccess'],
['tempo-e-atualizacao','Tempo e atualização','Escolha entre tempo de simulação, tempo não escalado e passo fixo.','TimeAccess pertence à sessão e à thread de despacho. Scale aceita valores finitos entre 0 e 4; zero congela a simulação e a nova escala tem efeito no próximo quadro.','Para uma animação independente de pausa, confira o relógio não escalado. Para física, respeite o passo apropriado. Não reutilize TimeAccess depois de encerrar Play.','TimeAccess'],
['thread-e-ponto-seguro','Thread e ponto seguro','Agendamento não concede acesso concorrente ao mundo.','Operações estruturais podem ser aceitas e aplicadas entre passos. Uma Task comum em outra thread não torna o acesso à cena seguro. APIs da sessão podem exigir a thread de despacho.','Use os mecanismos de corrotina e awaitable oferecidos pela engine. Observe cancelamento, término da sessão e resultado das operações rastreadas.','BehaviorAwaitables'],
['autoridade-de-transformacao','Autoridade de transformação','Escolha um responsável para publicar a pose do objeto.','Scripts, física, personagens, caminhos e restrições podem disputar a transformação. Um corpo simulado não deve ser movimentado como um objeto puramente visual sem respeitar sua autoridade.','TransformOwnedByPhysics é uma recusa explícita. Use força, impulso ou movimento cinemático conforme o corpo. Remover a física só para ocultar o erro muda o comportamento do jogo.','PhysicsBodyRuntime'],
['serializacao-e-migracao','Serialização e migração','Persistência depende de identidade, formato e recursos compatíveis.','O componente possui typeId e versão de payload. A cena precisa preservar relações e referências, não apenas números do Inspector. Leitura bem-sucedida não comprova que todos os recursos externos continuam disponíveis.','Preserve uma cópia anterior à migração. Reabra, confira objetos e propriedades e execute um cenário pequeno. Versão desconhecida não deve ser tratada como arquivo vazio.','ComponentIds'],
['limites-e-capacidades','Limites e capacidades','Diferencie contrato, backend, política e aparelho.','Uma propriedade pode ter consumidor no código e ainda depender do dispositivo ou da política de qualidade. Um item pesquisado no atlas não equivale a capacidade implementada.','Consulte os limites de cada componente e registre a configuração efetiva. Não transforme uma medição pontual em promessa de desempenho para todos os aparelhos.','WorldStatus'],
];
for(const [slug,title,description,meaning,practice,type] of concepts)guide(`conceitos/${slug}`,title,description,[['Contrato',meaning],['Aplicação prática',practice],['Referência',`Consulte ${api(type)}. O contrato de fonte e a execução em um dispositivo são evidências diferentes.`]]);

const systems=[
['input-e-acoes','Input e ações','O projeto define as ações; o comportamento consome seus valores.','InputAccess consulta ações por nome e por papéis. Axis, Axis2, Pressed, JustPressed e JustReleased atendem leituras diferentes. Verifique Exists antes de depender de uma ação opcional.','Configure vínculos e contexto, confirme o foco do gameplay e só então leia o valor. O editor pode capturar a entrada durante IDE, teclado, modal e gizmo. Rebinding e política de habilitação em runtime não são automaticamente alterações autorais.','InputAccess'],
['cameras','Câmeras','Projeção, controle de olhar e acompanhamento são contratos separados.','Camera define a lente e o enquadramento. CameraLook recebe controle de orientação. CameraFollow publica posição após física e animação e exige uma câmera no mesmo objeto.','Comece por uma Camera estática. Verifique planos próximo/distante e projeção. Depois adicione acompanhamento, alvo, offset e amortecimento. Não combine a câmera seguidora com outra autoridade física de pose.','CameraFollowRig'],
['renderizacao','Renderização','A imagem depende de cena, recursos, câmera e política gráfica.','Uma malha precisa de recurso válido e material; a câmera determina o enquadramento e o backend resolve as capacidades. Recursos importados e configurações autorais passam por etapas diferentes antes do desenho.','Ao investigar ausência visual, reduza a cena a uma malha, um material e uma câmera. Registre a configuração efetiva e não atribua um artefato à GPU antes de verificar referências, visibilidade e escala.','GameViewAccess'],
['iluminacao','Iluminação','Luzes e ambiente têm unidades e consumidores específicos.','O componente Light declara tipo, cor, intensidade e alcance, além de propriedades condicionais. A unidade depende do modo selecionado; uma escala legada e uma unidade fotométrica não são intercambiáveis.','Aumentar intensidade não resolve uma luz fora do alcance, descartada pelo orçamento ou sem suporte à sombra desejada. Confira a página do componente e a política efetiva. Faça comparações com exposição e câmera fixas.','Components.Light'],
['materiais','Materiais','Use parâmetros e recursos compatíveis com o material ativo.','MaterialSlot representa o acesso ao material de um slot. Malhas com vários materiais precisam do slot correto. Texturas, valores escalares, alfa e projeção UV afetam etapas diferentes do resultado.','Mude um parâmetro por vez. Confirme que uma textura de normal não está sendo tratada como cor e que a emissão é avaliada com exposição consistente. Evite editar todos os slots quando a intenção é alterar apenas uma superfície.','MaterialSlot'],
['importacao-glb','Importação GLB','Preserve a fonte e examine o que foi realmente importado.','GLB pode carregar geometria, materiais, texturas, hierarquia e animação. A presença dessas informações no arquivo não prova que todas as extensões ou comportamentos são executados pelo importador atual.','Confira recursos ausentes e avisos de importação. Abra a cena, revise escala, materiais e hierarquia e reabra o projeto. Dados preservados, fidelidade visual e comportamento executável devem ser avaliados separadamente.','AssetGuid'],
['fisica-3d','Física 3D','Corpos, colisores, consultas e eventos formam um sistema.','Collider define participação geométrica; PhysicsBody define o corpo e a autoridade da simulação. PhysicsAccess oferece consultas. Um MeshRenderer visível não substitui um collider.','Confira tipo de corpo, massa, camada, máscara e estado ativo. Use impulso ou força conforme o efeito desejado. Para consultar colisões, observe filtros e truncamento de resultados.','PhysicsAccess'],
['fisica-2d','Física 2D','Trate a simulação 2D como um contrato próprio.','Body2D, Collider2D, Joint2D e campos 2D compõem a família de física 2D. A referência mantém seus tipos separados da física 3D para evitar mistura de coordenadas e propriedades.','Consulte a fachada e o schema do componente 2D escolhido. Não use uma consulta 3D esperando encontrar um corpo apenas porque ele aparece na tela. Valide a composição e os filtros do mundo correto.','Physics2DAccess'],
['personagem','Personagem','Movimento de personagem tem autoridade e estado próprios.','O controlador de personagem recebe intenção de movimento e publica o resultado de contato com o mundo. GameObject expõe MoveCharacter, TryJumpCharacter e ReadCharacterState.','Passe orientação em radianos onde o contrato pede yawRadians. Verifique estado de apoio e retorno da tentativa de salto. Não some deslocamento visual por fora enquanto o controlador escreve a pose.','CharacterRuntimeState'],
['juntas','Juntas','Uma relação física precisa de corpos e referenciais coerentes.','Juntas restringem movimento entre corpos. Âncoras, eixos e limites têm significado no referencial declarado. A família 2D usa seu próprio componente.','Antes de ajustar rigidez ou limites, confira os corpos ligados, suas poses e a existência de uma configuração que satisfaça a restrição. Uma junta tentando corrigir uma montagem impossível pode produzir instabilidade.','Components.Joint'],
['campos-fisicos','Campos físicos','Aplique influência espacial sem esconder os alvos e limites.','Gravidade, vento, arrasto e campo radial possuem componentes próprios em 3D e 2D. A configuração define influência e consumo no sistema físico correspondente.','Confira quais corpos estão dentro do campo, suas camadas e o espaço dos vetores. Comece com um corpo isolado e uma intensidade pequena para distinguir influência do campo da gravidade global.','PhysicsFieldRuntime'],
['animacao','Animação','Um clipe válido também precisa pertencer ao componente.','AnimationPlayer controla a reprodução no componente Animation. A lista de clips e o clip padrão são referências a recursos; uma identidade existente fora dessa lista pode produzir ClipNotInComponent.','Confira importação, vínculo do clip e alvo antes de ajustar velocidade ou mistura. Para malhas deformáveis, confirme esqueleto e qualidade de skinning; tocar uma animação não cria ossos ausentes.','AnimationPlayer'],
['audio','Áudio','Controle reprodução e lifetime de uma voz.','AudioVoice expõe Play, Pause, Resume, Stop, Seek e Snapshot. O componente e o recurso de áudio precisam continuar válidos durante o uso. Audio Listener e Audio Bus fazem parte da composição.','Confirme o clip, ganho, bus e listener. Observe Snapshot antes de culpar o arquivo; pausa, término e estado inválido são situações diferentes. Esta referência não constitui teste de saída de áudio em aparelho.','AudioVoice'],
['ui-de-jogo','UI de jogo','Canvas, elementos, foco e eventos participam do mesmo fluxo.','GuiAccess encontra e cria elementos e permite selecionar um canvas. GuiElement expõe layout, estilo, ações, texto e estado de interação. Poll entrega eventos que precisam ser interpretados pelo tipo.','Em cenas com vários canvases, use o proprietário e a instância corretos. Confirme enabled, ordem, foco e captura. Um botão visível pode estar coberto por outra superfície que recebe a entrada.','GuiAccess'],
['curvas-e-caminhos','Curvas e caminhos','Separe o recurso geométrico do objeto que o percorre.','O componente Path contém o caminho; PathFollow consome uma referência para publicar movimento. CurvePath e PathFollower oferecem operações especializadas.','Configure um caminho com pontos válidos, vincule o seguidor e confira espaço, orientação e política de término. Não combine outro escritor de transformação sem definir a autoridade.','CurvePath'],
['timers','Timers','Agende comportamento com duração e dono explícitos.','O componente Timer tem uma fachada gerada chamada GameTimer. Behavior.TimerElapsed recebe o identificador da instância e a contagem de expirações acumuladas no quadro.','Distinga timers por instância. Um quadro longo pode entregar mais de uma expiração. Não suponha que o callback seja chamado uma vez para cada tick; use o parâmetro count.','Components.GameTimer'],
['tweens','Tweens','Uma transição precisa de uma propriedade elegível e um dono.','NumberTween representa uma operação numérica que pode pausar, retomar, cancelar e ser descartada. O schema identifica campos tweenable; nem todo número aceita a operação.','PropertyNotTweenable, PropertyAlreadyTweening e PropertyWrittenExternally distinguem inelegibilidade e disputa de escrita. Resolva o escritor concorrente antes de reiniciar continuamente a transição.','NumberTween'],
['corrotinas','Corrotinas','Divida trabalho em etapas ligadas ao lifecycle.','Behavior oferece StartCoroutine e StartAsync. Coroutine informa estado, falha e se o trabalho permanece ativo. BehaviorAwaitables fornece os pontos de espera da engine.','Associe a tarefa ao Behavior e respeite cancelamento. Uma Task arbitrária não autoriza acessar o mundo em outra thread. Pare ou libere trabalho que não faz sentido após remover o objeto.','BehaviorAwaitables'],
['troca-de-cena','Troca de cena','Escolha entre substituir o mundo e acrescentar uma cena.','Scenes.Load pede substituição no fim do quadro. Scenes.LoadAdditive acrescenta conteúdo sob um contêiner e pode receber um pai. Names lista as cenas do projeto.','Use um nome existente e não conserve referências ao mundo substituído. A troca chama lifecycle dos comportamentos; não confunda o mundo novo com o documento autoral que volta ao parar.','ScenesAccess'],
['persistencia','Persistência','Grave progresso em um namespace pertencente ao projeto.','SaveStore oferece chaves tipadas e arquivos. Alterações de chaves são confirmadas por Flush; arquivos independentes são confirmados imediatamente. O contrato possui cotas de tamanho.','Use chaves estáveis, valores de fallback para ausência e um tipo consistente por chave. Leitura com tipo diferente é erro, não conversão automática. Preserve a possibilidade de recuperação e não escreva fora dos caminhos permitidos.','SaveStore'],
['aleatoriedade','Aleatoriedade','Use um fluxo explícito para repetir uma sequência local.','RandomStream recebe seed e stream e fornece inteiros, valores, distribuições e amostras geométricas. Capture e Restore conservam o estado do fluxo.','Range usa limite superior exclusivo. A mesma seed só é comparável com a mesma versão do algoritmo e a mesma ordem de chamadas. Isso não prova determinismo de toda a física ou do jogo entre plataformas.','RandomStream'],
];
const typeLink=name=>name.startsWith('Components.')?`[${name}]($BASE/api/astra-components-${name.split('.')[1].toLowerCase()}/)`:api(name);
for(const [slug,title,description,contract,usage,type] of systems)guide(`sistemas/${slug}`,title,description,[['Como o sistema se conecta',contract],['Configuração e cuidados',usage],['API e composição',`Consulte ${typeLink(type)} e o [catálogo de componentes]($BASE/componentes/) para assinaturas e propriedades. O suporte em um aparelho deve ser conferido com os recursos e a versão efetivamente instalados.`]]);

const diagnostics=[
['erros-de-compilacao','Erros de compilação','O script não compila ou o Behavior não fica disponível.','Assinatura de outra engine; namespace incorreto; tipo renomeado; identificador duplicado; dependência de script ausente.','Leia o primeiro erro com arquivo e linha. Compare a assinatura com esta API. Reduza o script a um Behavior com Update vazio e reintroduza as chamadas até localizar a incompatibilidade.','Uma compilação sem erros permite passar à verificação de anexação e lifecycle; ainda não comprova comportamento de gameplay.','Behavior'],
['componente-indisponivel','Componente indisponível','O Add ou a API recusa a composição.','Dependência ausente, conflito, segunda instância de um tipo único, tipo não registrado ou mudança estrutural proibida em Play.','Abra a ficha do componente. Confira requirements, conflicts, multiplicidade e mutabilidade. Interprete ComponentUnavailable, ComponentMissing e ComponentInUse como causas distintas.','A composição deve ser aceita com todas as dependências presentes e sem conflito.','Component'],
['handle-invalido','Handle inválido','Uma operação aponta para objeto removido ou outra sessão.','O alvo foi destruído, o Play foi reiniciado, a cena foi trocada ou uma tarefa conservou referência além do lifetime do dono.','Confira IsAlive e a origem da referência. Refaça a resolução na sessão atual. Cancele callbacks que sobreviveriam ao objeto. Não suprima StaleHandle ou ForeignWorld em um loop por frame.','O acesso deve usar o alvo da sessão atual sem reutilizar o handle antigo.','WorldStatus'],
['objeto-nao-se-move','Objeto não se move','Uma transformação não produz o efeito esperado.','Behavior desabilitado; objeto inativo; delta zero; câmera não enquadra o alvo; escrita posterior por outro sistema; autoridade física.','Comece sem física em um objeto visual. Verifique o callback e a unidade. Observe TransformOwnedByPhysics e o escritor responsável pela pose. Para corpos, use a API física adequada.','Uma mudança isolada deve aparecer na pose e na câmera usada em Play.','GameObject'],
['camera-sem-imagem','Câmera sem imagem','A cena aparece no editor, mas o Play não enquadra conteúdo.','Câmera ativa diferente da esperada, orientação, near/far, escala, recurso ausente ou estado de visibilidade.','Use uma cena pequena com geometria conhecida. Confira pose da câmera de jogo, projeção e planos de recorte. Compare a câmera selecionada com a usada no mundo de Play.','O mesmo objeto de referência deve aparecer de forma estável no enquadramento do jogo.','GameViewAccess'],
['colisao-ausente','Colisão ausente','Objetos atravessam a geometria ou a consulta não encontra o alvo.','Há malha visual sem colisor; camada/máscara exclui o par; mistura de física 2D/3D; corpo inativo; geometria inadequada.','Confira a composição, o tipo de corpo e os filtros. Use formas simples e movimento moderado para isolar configuração de problemas de velocidade ou geometria.','A configuração mínima deve produzir contato ou hit antes de reintroduzir a geometria complexa.','PhysicsAccess'],
['input-sem-resposta','Input sem resposta','A ação existe no código, mas não responde ao controle.','Nome de ação diferente, vínculo ausente, contexto desabilitado, grupo de dispositivo excluído ou foco capturado pelo editor.','Consulte Exists e ActionState. Feche modal/teclado, devolva foco ao gameplay e confira os vínculos do projeto. Verifique Pressed versus JustPressed conforme a mecânica.','A fase e o valor devem mudar ao pressionar e voltar ao estado esperado ao soltar.','InputAccess'],
['asset-nao-encontrado','Asset não encontrado','Um componente referencia um recurso que não pode ser resolvido.','Identidade não registrada, arquivo movido, dependência externa ausente, importação incompleta ou tipo de recurso incompatível.','Confira o registro e o resultado da importação. Preserve a fonte e a mensagem. Diferencie UnknownResource de ResourceTypeMismatch; não atribua um GUID arbitrário para ocultar o erro.','O recurso deve resolver, aparecer na cena e continuar resolvendo após reabrir o projeto.','AssetGuid'],
['cena-nao-reabre','Cena não reabre','A leitura do projeto falha ou os dados não correspondem ao salvo.','Formato incompatível, arquivo incompleto, referência de recurso ausente ou tentativa de abrir conteúdo de outra geração.','Faça uma cópia do arquivo antes de agir. Registre versão e mensagem de leitura. Confira backups e recursos. Não salve uma cena vazia sobre o único arquivo com falha.','Reabra uma cópia recuperada e verifique objetos, propriedades e recursos antes de substituir a original.','ScenesAccess'],
['play-nao-inicia','Play não inicia','A sessão de runtime não chega a executar o cenário.','Compilação inválida, script ausente, recurso necessário não resolvido ou falha durante inicialização de um comportamento.','Confira diagnóstico de compilação e lifecycle. Tente uma cena mínima sem o último componente adicionado. Identifique a primeira falha em Awake/Start em vez de seguir erros em cascata.','A sessão deve iniciar, atualizar e encerrar sem referências conservadas da execução anterior.','Behavior'],
['ui-sem-evento','UI sem evento','Um controle visível não entrega a interação esperada.','Canvas errado, elemento desabilitado, sobreposição capturando input, foco, nome diferente ou fila de eventos não consumida.','Selecione explicitamente o canvas correto. Confira o elemento com TryFind, seu estado e interação. Consuma Poll e compare o Kind do evento.','Pressionar e soltar deve produzir o evento correto sem ativar elementos que estejam atrás.','GuiAccess'],
['audio-sem-reproducao','Áudio sem reprodução','Uma voz não produz som audível.','Clip ausente, voz parada/pausada, ganho baixo, bus silenciado, listener ou lifetime inválido.','Leia Snapshot e confira o recurso. Teste uma voz com configuração simples e volume conhecido. Verifique o áudio do dispositivo antes de alterar a cena inteira.','Play, Pause, Resume e Stop devem refletir no estado e na saída observada.','AudioVoice'],
];
for(const [slug,title,description,causes,steps,confirm,type] of diagnostics)guide(`diagnostico/${slug}`,title,description,[['Causas a conferir',causes],['Investigar',steps],['Confirmar a correção',confirm],['Contrato relacionado',api(type)]]);

const performance=[
['como-medir','Como medir','Construa uma comparação reproduzível.','Registre build, aparelho/GPU, cena, resolução, qualidade, duração, aquecimento e condições térmicas. Diferencie Debug com validação de uma build de desempenho.','Compare o mesmo percurso e a mesma câmera. Guarde tempos de CPU/GPU e distribuição de frames, não apenas um FPS instantâneo. Metas de 60/120 FPS não são resultados medidos.'],
['cpu-e-atualizacao','CPU e atualização','Descubra em qual etapa o quadro gasta tempo.','Scripts, transformações, física, culling e submissão têm custos diferentes. Uma espera pela GPU pode aparecer como tempo de CPU sem significar trabalho útil do processador.','Reduza uma carga de cada vez e compare o perfil. Evite procurar objetos por nome repetidamente em Update quando uma referência válida pode ser conservada durante a sessão.'],
['gpu-e-draw-calls','GPU e draw calls','Mais FPS exige localizar o custo dominante.','Draw calls são apenas uma dimensão: pixels, sombras, transparência, largura de banda e complexidade do shader também consomem GPU. Diminuir chamadas não garante ganho se o gargalo estiver em outro estágio.','Compare a mesma imagem e configuração. Se reduzir resolução melhora muito o tempo de GPU, investigue custo por pixel. Registre qualquer mudança visual junto da medição.'],
['texturas-e-memoria','Texturas e memória','Considere o tamanho residente, não apenas o arquivo comprimido.','Dimensões, formato, mipmaps e número de recursos simultâneos influenciam memória e bandwidth. Um arquivo pequeno no disco pode resultar em uma imagem grande na GPU.','Revise materiais e texturas repetidas. Compare qualidade em distâncias reais de câmera. Não remova mipmaps ou diminua resolução sem verificar estabilidade visual e aliasing.'],
['alocacoes-c','Alocações C#','Evite criar lixo continuamente nos caminhos por frame.','Coleções temporárias, strings e materialização de consultas podem gerar pressão no coletor. Algumas APIs retornam arrays ou listas; confira a assinatura e a frequência de uso.','Conserve referências enquanto forem válidas e faça consultas caras na frequência necessária. Não transforme otimizações locais em estado global que sobreviva indevidamente ao Play.'],
['fisica-e-queries','Física e queries','Meça corpos ativos e consultas como cargas separadas.','A quantidade de pares, formas, contatos e passos influencia a simulação. RayCastAll e Overlap também dependem da capacidade solicitada e podem indicar truncamento.','Use filtros compatíveis com a necessidade da mecânica. Observe truncated e não interprete uma lista limitada como todos os objetos do mundo. Compare o custo mantendo a mesma cena.'],
['carga-de-cenas','Carga de cenas','Separe I/O, importação, criação e publicação.','Abrir uma cena pode envolver leitura, resolução de recursos, derivados e criação de objetos. Medir só o clique até a primeira imagem não explica qual etapa causa a espera.','Compare primeira abertura e reabertura com cache. Registre recursos e tamanho. Não declare ganho se a versão rápida apenas deixou de carregar parte do conteúdo.'],
['termica-e-bateria','Térmica e bateria','Desempenho sustentado exige uma janela de observação.','A frequência e o custo podem mudar com aquecimento, energia, brilho e limite de frames. Temperatura de bateria isolada não determina a temperatura ou throttling do SoC.','Use build e condições comparáveis, warmup e duração registrada. Anote queda ao longo do tempo e preserve o mesmo cenário. Um pico de FPS não comprova estabilidade térmica.'],
['qualidade-e-resolucao','Qualidade e resolução','Publique a configuração efetiva junto de qualquer métrica.','Resolução dinâmica, sombras, luzes, materiais e efeitos alteram custo e imagem. Dois números de FPS não são comparáveis se uma execução reduziu a resolução sem registrar isso.','Fixe ou registre a escala real. Capture a mesma câmera para comparar perda visual. Distinga opção autoral, política solicitada e capacidade resolvida pelo backend.'],
['orcamentos-por-aparelho','Orçamentos por aparelho','Trate cada perfil como evidência específica.','Um orçamento depende de GPU, driver, resolução, cenário, energia e temperatura. Não transfira a medição de um aparelho para todos os modelos com uma classificação comercial parecida.','Defina uma cena representativa e acompanhe média, p95/p99 e estabilidade. Este portal não publica uma tabela universal de desempenho nem promete uma taxa de frames sem ensaio correspondente.'],
];
for(const [slug,title,description,meaning,method] of performance)guide(`desempenho/${slug}`,title,description,[['O que observar',meaning],['Método de comparação',method],['Registro mínimo','Guarde versão, configuração, cena e resultado junto da evidência. Ensaios de host, build Android, instalação e execução física são etapas distintas.']]);

export const examples=[{id:'rotate-object',filename:'RotateObject.cs',code:rotate,description:'Gira um objeto visual no eixo Y local a 0,5 rad/s.',prerequisites:'Objeto sem autoridade física, geometria visível, Behavior anexado.'}];
examples.push(...heartExamples);
function recipe(slug,title,description,setup,code,expect,limits,type){
  const body=`## Composição da cena\n\n${setup}\n\n## Implementação\n\n${code?'```csharp\n'+code+'\n```':'Configure os valores pelo Inspector e consulte a API relacionada antes de adicionar controle por script.'}\n\n## Resultado esperado\n\n${expect}\n\n## Cuidados\n\n${limits}\n\nConsulte ${typeLink(type)}. As instruções descrevem o cenário proposto; a execução em dispositivo não foi realizada nesta publicação.`;
  add(`receitas/${slug}`,title,description,body,{kind:'recipe'});
}
recipe('girar-um-objeto','Girar um objeto','Integre velocidade angular com o delta da atualização.','Objeto visual sem corpo ou personagem escrevendo sua pose; câmera enquadrada.',rotate,'Rotação local contínua a 0,5 rad/s.','Use radianos e multiplique por deltaTime uma única vez. Uma esfera sem detalhes pode esconder visualmente a rotação.','GameObject');
const movement=`using Astra;
using System.Numerics;

[ComponentId("docs.move-local")]
public sealed class MoveLocal : Behavior
{
    public override void Update(float deltaTime)
    {
        Object.Translate(Vector3.UnitZ * deltaTime,
                         TransformSpace.Local);
    }
}`;
examples.push({id:'move-local',filename:'MoveLocal.cs',code:movement,description:'Desloca um objeto visual no seu eixo Z local.',prerequisites:'Objeto visual sem autoridade física e câmera enquadrada.'});
recipe('mover-em-espaco-local','Mover em espaço local','Mova na direção do objeto, mesmo quando ele está rotacionado.','Objeto visual com orientação diferente da identidade, sem física comandando a pose.',movement,'O objeto percorre seu eixo Z local; rotacioná-lo muda a direção do movimento.','Compare com TransformSpace.World mantendo a mesma rotação. Não use este exemplo como motor de personagem físico.','GameObject');
const spawn=`using Astra;

[ComponentId("docs.spawn-temporary")]
public sealed class SpawnTemporary : Behavior
{
    public override void Start()
    {
        var child = Object.CreatePrimitive(PrimitiveType.Cube);
        child.Name = "Cubo temporário";
        child.Destroy(3.0);
    }
}`;
examples.push({id:'spawn-temporary',filename:'SpawnTemporary.cs',code:spawn,description:'Cria um cubo e solicita destruição após três segundos.',prerequisites:'Behavior em objeto ativo; câmera precisa enquadrar a posição de criação.'});
recipe('criar-e-remover-objetos','Criar e remover objetos','Associe criação e lifetime a uma intenção de gameplay.','Objeto com Behavior e câmera capaz de ver sua posição.',spawn,'Um cubo é criado e a remoção é solicitada após o atraso.','A composição da primitiva depende do contrato da engine. Não conserve o handle após destruição; mudanças estruturais seguem o ponto seguro.','GameObject');
recipe('encontrar-componentes','Encontrar componentes','Trate ausência como uma possibilidade real.','Objeto que pode ou não possuir Light.',`var light = Object.GetComponent(ComponentIds.Light);
if (light is not null)
{
    light.SetFloat("intensity", 2.0f);
}`,'Somente o componente encontrado é editado.','Trecho para uso dentro de um Behavior. Multiplicidade exige escolher a instância certa; não faça buscas sem necessidade a cada frame.','Component');
recipe('camera-acompanhando-alvo','Câmera acompanhando alvo','Separe alvo, offset e amortecimento.','Uma Camera com CameraFollow no mesmo objeto; alvo válido na mesma sessão.',`var component = Object.GetComponent(ComponentIds.CameraFollow);
var target = Object.FindInWorld("Alvo");
if (component is not null && target is not null)
{
    var follow = component.CameraFollow();
    follow.Target = target.AsReference();
    follow.Offset = new System.Numerics.Vector3(0, 2, -5);
    follow.DampingSeconds = 0.2f;
}`,'A posição da câmera acompanha o alvo com o offset configurado.','Trecho de inicialização de um Behavior na câmera. O acompanhamento descrito não cria automaticamente um sistema de enquadramento, oclusão ou orientação.','CameraFollowRig');
recipe('ler-uma-acao','Ler uma ação','Use o nome configurado pelo projeto.','Uma ação chamada Interagir configurada com um vínculo.',`if (Input.Exists("Interagir") && Input.JustPressed("Interagir"))
{
    Object.Name = "Interação recebida";
}`,'No quadro do pressionamento, o nome do objeto muda.','Trecho para Update. Se a ação usa outro nome, ajuste-o. Confira foco, contexto e grupos de dispositivo.','InputAccess');
recipe('interagir-com-raycast','Interagir com raycast','Consulte a geometria física na direção do objeto.','Objeto emissor, alvo com collider e camadas incluídas no filtro.',`var hit = Physics.RayCast(Object.WorldPosition,
    Object.Forward * 5.0f, QueryFilter.Default.Ignoring(Object));
if (hit is { } contact)
{
    contact.Object.Name = "Alvo encontrado";
}`,'Um alvo físico encontrado pelo raio recebe o nome indicado.','Trecho para uma ação de interação em Behavior. O vetor carrega a extensão da consulta; não substitua por uma direção unitária quando deseja outro alcance. O exemplo altera nome, não implementa inventário ou regras de interação.','PhysicsAccess');
recipe('reagir-a-colisao','Reagir a colisão','Receba um evento e mantenha o contexto do contato.','Composição física capaz de produzir contatos e Behavior no objeto receptor.',`public override void CollisionEnter(Collision collision)
{
    var other = Resolve(collision.Other);
    if (other is not null)
        Object.Name = "Contato com " + other.Name;
}`,'O nome do receptor identifica o outro objeto quando o contato começa.','Trecho dentro de uma classe Behavior. Normal pode ser nula; triggers têm callbacks próprios e não equivalem a contato sólido.','Collision');
recipe('porta-cinematica','Porta cinemática','Uma porta móvel precisa manter a autoridade física coerente.','Porta com collider e corpo configurado como cinemático; botão ou sensor separado para a interação.',null,'A porta percorre uma pose aberta/fechada sem atravessar a parede por erro de montagem.','Antes de escrever o movimento, confira a API de corpo da versão. Não aplique o exemplo de Translate para um corpo dinâmico. Defina duração, reversão e comportamento ao encontrar obstáculo; esta receita descreve a composição, não entrega um controlador completo de porta.','PhysicsBodyRuntime');
recipe('aplicar-impulso','Aplicar impulso','Aplique um impulso no ponto de mundo escolhido.','Corpo dinâmico com collider e massa válida.',`var body = Object.PhysicsBody();
body.AddImpulseAtPosition(
    new System.Numerics.Vector3(0, 2, 0), body.CenterOfMass);`,'O corpo recebe impulso vertical no centro de massa.','Trecho executado uma vez por ação. Aplicar impulso em todo Update muda a mecânica e faz o resultado depender da frequência; não confunda impulso com força contínua.','PhysicsBodyRuntime');
recipe('contagem-regressiva','Contagem regressiva','Dispare um Timer sem depender da contagem de frames.','Componente Timer no mesmo objeto do Behavior.',`public override void Start()
{
    var component = Object.GetComponent("astra.time.timer");
    if (component is not null)
        component.Timer().Start(5.0);
}

public override void TimerElapsed(ulong timerInstanceId, uint count)
{
    Object.Name = "Tempo encerrado";
}`,'O evento altera o nome após o intervalo.','Trecho dentro de Behavior. Confira Repeat e IgnoreTimeScale. Se há vários timers, compare timerInstanceId e considere count.','Components.GameTimer');
recipe('transicao-com-tween','Transição com tween','Anime somente uma propriedade elegível.','Uma Camera no objeto e nenhum outro escritor do campo de visão.',`var camera = Object.GetComponent(ComponentIds.Camera);
if (camera is not null)
{
    var transition = camera.TweenFloat("vertical_fov", 75.0f, 1.0f);
    // Conserve a operação se precisar consultar ou cancelar a transição.
}`,'O campo de visão progride até 75 graus ao longo de um segundo.','Trecho de inicialização com using Astra. A propriedade é marcada como tweenable no contrato; trate conflito de escrita e cancelamento conforme o lifetime do Behavior.','NumberTween');
const save=`using Astra;

[ComponentId("docs.visit-counter")]
public sealed class VisitCounter : Behavior
{
    public override void Start()
    {
        long visits = Save.GetInt64("visits", 0) + 1;
        Save.SetInt64("visits", visits);
        Save.Flush();
        Object.Name = "Visita " + visits;
    }
}`;
examples.push({id:'visit-counter',filename:'VisitCounter.cs',code:save,description:'Incrementa e grava uma chave tipada ao iniciar.',prerequisites:'Projeto com SaveStore disponível; Behavior ativo.'});
recipe('salvar-progresso','Salvar progresso','Confirme alterações de chaves explicitamente.','Behavior em projeto com namespace de persistência disponível.',save,'A contagem aumenta a cada nova inicialização do Behavior e é gravada com Flush.','A chave deve manter o mesmo tipo entre versões. Trate erros de I/O e não use Flush a cada frame.','SaveStore');
recipe('trocar-de-cena','Trocar de cena','Solicite uma cena que pertence ao projeto.','Duas cenas registradas e nome de destino conferido em Scenes.Names.',`Scenes.Load("segunda-cena");`,'O mundo é substituído no fim do quadro corrente.','Trecho dentro de Behavior; o nome é um exemplo e precisa existir no seu projeto. Não faça a solicitação continuamente em Update nem conserve referências do mundo antigo.','ScenesAccess');
recipe('botao-de-ui','Botão de UI','Consuma o evento do controle certo.','Canvas com um botão chamado Comecar e Behavior consultando esse canvas.',`while (Gui.Poll(out var message))
{
    if (message.Kind == GuiEventKind.Click &&
        message.Element.Name == "Comecar")
    {
        Object.Name = "Botão acionado";
    }
}`,'Um click no controle nomeado altera o objeto receptor.','Trecho de Update. Se houver vários canvases, obtenha o GuiAccess correto. Esta receita consome a fila; coordene os consumidores para não retirar eventos de outro sistema.','GuiAccess');
recipe('controle-de-volume','Controle de volume','Ajuste o parâmetro de áudio correspondente ao escopo desejado.','AudioSource com clip válido, listener e bus configurados.',null,'O ajuste de ganho/mute no componente altera a reprodução da fonte.','Escolha se o controle atua em uma voz, um bus ou na política global. Confira os limites da propriedade no componente; um slider visual sem escrita na fonte não controla áudio.','Components.AudioSource');
recipe('percorrer-caminho','Percorrer caminho','Conecte o seguidor ao caminho antes de iniciar.','Path com pontos válidos e PathFollow no objeto que deve se mover.',`var component = Object.GetComponent(ComponentIds.PathFollow);
if (component is not null)
    component.FollowPath().Restart();`,'O seguidor reinicia a execução do caminho atribuído.','Trecho de Behavior. Atribua a referência do caminho e configure progressão/orientação no Inspector. Restart não cria um caminho nem corrige disputa de autoridade.','PathFollower');
recipe('instanciar-prefab','Instanciar prefab','Use a identidade de um recurso prefab do projeto.','Prefab importado/registrado e AssetGuid válido obtido de uma propriedade de recurso.',`// prefabAsset é um AssetGuid de recurso atribuído pelo projeto.
var instance = Object.InstantiatePrefab(prefabAsset);
instance.Name = "Instância";`,'Uma instância do recurso é criada sob o contexto de autoria definido pela API.','Trecho contextual: prefabAsset deve ser fornecido pelo projeto. Não invente um GUID e não confunda instanciar com copiar o arquivo de cena.','GameObject');

guide('exemplos/como-executar-exemplos','Como executar exemplos','Use os scripts pequenos para isolar um comportamento.',[
['Downloads desta publicação','Os microexemplos são arquivos C# independentes escritos para o portal. Eles não incluem o código da engine nem um projeto completo. Acompanhe os pré-requisitos e o estado no [manifesto]($BASE/ia/manifesto-de-exemplos/).'],
['Preparação','Crie uma cena pequena, adicione geometria e câmera, crie/anexe o script e compile no editor. Inicie Play e compare o resultado com a receita. Ao terminar, pare e confira a cena autoral.'],
['Escolha um exemplo','- [Rotação]($BASE/receitas/girar-um-objeto/)\n- [Movimento local]($BASE/receitas/mover-em-espaco-local/)\n- [Objeto temporário]($BASE/receitas/criar-e-remover-objetos/)\n- [Persistência]($BASE/receitas/salvar-progresso/)'],
['Projetos maiores','Os jogos a seguir são referências de curadoria baseadas na documentação interna existente. O portal não oferece downloads de pacotes ainda não auditados e não afirma que a distribuição atual já os inclui.']]);
guide('exemplos/cena-minima-de-lifecycle','Cena mínima de lifecycle','Observe a ordem das fases sem misturar vários sistemas.',[
['Cena','Use um objeto ativo com Behavior e uma câmera. Mantenha o script sem dependências de física, áudio ou recursos externos.'],
['Experimento','Adicione marcadores de diagnóstico em Awake, Enable, Start, Update, Disable, Stop e Destroy conforme a API de logging da instalação. Evite emitir mensagem em todo Update durante uma sessão longa.'],
['O que conferir','Inicie, desabilite/habilite o comportamento, remova o objeto e encerre Play em execuções separadas. Registre a ordem observada e compare os callbacks com a referência de Behavior. Este é um roteiro de investigação, sem log de execução fabricado.']]);
